import heapq

def match(orders):
    trades = []
    buy_heap = []   # heap of (-price, seq, id) for resting buy limit orders
    sell_heap = []  # heap of (price, seq, id) for resting sell limit orders
    info = {}       # id -> {'side':..., 'price':..., 'qty':..., 'active':...}
    seq = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in info and info[oid]['active'] and info[oid]['qty'] > 0:
                info[oid]['active'] = False
            seq += 1
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            seq += 1
            continue

        info[oid] = {'side': side, 'price': price, 'qty': qty, 'active': True}
        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                top_price, top_seq, top_id = sell_heap[0]
                # lazy deletion of stale/inactive/filled entries
                if (top_id not in info) or (not info[top_id]['active']) or (info[top_id]['qty'] <= 0):
                    heapq.heappop(sell_heap)
                    continue
                if typ != 'market' and top_price > price:
                    break
                heapq.heappop(sell_heap)
                trade_qty = min(remaining, info[top_id]['qty'])
                trades.append([oid, top_id, top_price, trade_qty])
                remaining -= trade_qty
                info[top_id]['qty'] -= trade_qty
                if info[top_id]['qty'] > 0:
                    heapq.heappush(sell_heap, (top_price, top_seq, top_id))
                else:
                    info[top_id]['active'] = False

            info[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                heapq.heappush(buy_heap, (-price, seq, oid))
                info[oid]['active'] = True
            else:
                info[oid]['active'] = False

        else:  # sell
            while remaining > 0 and buy_heap:
                neg_price, top_seq, top_id = buy_heap[0]
                top_price = -neg_price
                if (top_id not in info) or (not info[top_id]['active']) or (info[top_id]['qty'] <= 0):
                    heapq.heappop(buy_heap)
                    continue
                if typ != 'market' and top_price < price:
                    break
                heapq.heappop(buy_heap)
                trade_qty = min(remaining, info[top_id]['qty'])
                trades.append([top_id, oid, top_price, trade_qty])
                remaining -= trade_qty
                info[top_id]['qty'] -= trade_qty
                if info[top_id]['qty'] > 0:
                    heapq.heappush(buy_heap, (neg_price, top_seq, top_id))
                else:
                    info[top_id]['active'] = False

            info[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                heapq.heappush(sell_heap, (price, seq, oid))
                info[oid]['active'] = True
            else:
                info[oid]['active'] = False

        seq += 1

    return trades

